_LOGGER = logging.getLogger(__name__)

_HERE = os.path.dirname(os.path.abspath(__file__))
# Pre-v2.63 default: a single shared token.json for every account. Two
# MagicMirror module instances (or module blocks) configured with DIFFERENT
# Kia accounts both fell back to this same file -- each one's token refresh
# silently overwrote the other's, so whichever account polled last would
# leave the OTHER account authenticating with the wrong (or freshly revoked)
# token on its next cycle. See account_token_file() / DEFAULT_TOKEN_FILE's
# remaining role as a one-time migration source, below.
DEFAULT_TOKEN_FILE = os.path.join(_HERE, "token.json")


def _account_hash(region, brand, username) -> str:
    """sha256(REGION|BRAND|username), truncated -- same non-cryptographic
    identity-hashing idea node_helper.js's _idHash() uses for cache files
    (there's no Node/Python code-sharing path for this one, so it's a
    separate implementation of the same idea). Token identity is scoped to
    the ACCOUNT (region+brand+username), not a specific vehicle -- one Kia
    login's token is shared across every vehicle on that account."""
    raw = f"{str(region).upper()}|{str(brand).upper()}|{str(username).strip().lower()}"
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]


def account_token_file(job) -> str:
    """The token file THIS job's account owns -- distinct per (region, brand,
    username), so two differently-configured accounts never share one file."""
    h = _account_hash(
        job.get("region", "USA"), job.get("brand", "KIA"), job.get("username", "")
    )
    return os.path.join(_HERE, f"token-{h}.json")


def _auth_state_file(job) -> str:
    """Per-account, alongside the token file (same _HERE + account-hash
    convention account_token_file() already uses)."""
    h = _account_hash(
        job.get("region", "USA"), job.get("brand", "KIA"), job.get("username", "")
    )
    return os.path.join(_HERE, f"authstate-{h}.json")


# A live token that fails to re-auth means Kia is rejecting THIS account's
# login, not "the network blipped" -- retrying it on the normal poll/retry
# schedule just repeats the same failing login call over and over, which is
# exactly the kind of pattern that gets an account rate-limited or locked
# out (a real incident: repeated failed re-logins during a setup retry loop
# preceded a user's Kia Connect account getting locked). AUTH_FAILURE_
# THRESHOLD consecutive failures within AUTH_FAILURE_WINDOW_SEC trips a
# cooldown -- connect() then refuses to even attempt check_and_refresh_
# token() again until it expires, so a broken login stops generating any
# further traffic to Kia at all instead of merely slowing down.
AUTH_FAILURE_THRESHOLD = 3
AUTH_FAILURE_WINDOW_SEC = 15 * 60
AUTH_COOLDOWN_BASE_MIN = 30
AUTH_COOLDOWN_MAX_MIN = 240  # 4h ceiling -- still eventually retries on its own


def _load_auth_state(path) -> dict:
    try:
        with open(path, encoding="utf-8") as fh:
            state = json.load(fh)
        return state if isinstance(state, dict) else {}
    except Exception:
        return {}


def _save_auth_state(path, state) -> None:
    try:
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(state, fh)
    except OSError:
        pass


def _cooldown_remaining_sec(state, now=None) -> float:
    """0 if not currently in a cooldown window, else seconds left in it."""
    now = time.time() if now is None else now
    until = state.get("cooldownUntil")
    if until is None:
        return 0.0
    return max(0.0, until - now)


def _record_auth_failure(state, now=None) -> dict:
    """New state after one more consecutive auth failure. Escalates into
    (and lengthens) a cooldown once AUTH_FAILURE_THRESHOLD is reached
    within the window; resets the count outside the window (an isolated
    failure weeks apart from the next isn't "repeated")."""
    now = time.time() if now is None else now
    last = state.get("lastFailureAt")
    count = state.get("consecutiveFailures", 0)
    if last is None or (now - last) > AUTH_FAILURE_WINDOW_SEC:
        count = 0
    count += 1
    new_state = dict(state)
    new_state["consecutiveFailures"] = count
    new_state["lastFailureAt"] = now
    if count >= AUTH_FAILURE_THRESHOLD:
        prior = state.get("cooldownsTriggered", 0)
        minutes = min(AUTH_COOLDOWN_BASE_MIN * (2 ** prior), AUTH_COOLDOWN_MAX_MIN)
        new_state["cooldownUntil"] = now + minutes * 60
        new_state["cooldownsTriggered"] = prior + 1
        new_state["consecutiveFailures"] = 0  # this window's count is spent
    return new_state


def _migrate_legacy_token(token_file, account_hash) -> None:
    """One-time migration off the old shared token.json, mirroring
    node_helper.js's migrateLegacyCache(): adopt (rename) the legacy file
    ONLY if it's never been tagged with an account's identity (a fresh
    upgrade from a pre-v2.63, single-account-only install) -- a legacy file
    already tagged for a DIFFERENT account must never be adopted here, or a
    second account set up after the first already migrated would silently
    steal the first account's still-in-use token."""
    if os.path.exists(token_file) or not os.path.exists(DEFAULT_TOKEN_FILE):
        return
    try:
        with open(DEFAULT_TOKEN_FILE, encoding="utf-8") as fh:
            raw = json.load(fh)
    except Exception:
        return  # unreadable/corrupt -- not a safe migration candidate
    if not (isinstance(raw, dict) and not raw.get("_kiaAccessAccountHash")):
        return  # already tagged (for this or another account) -- never adopt
    try:
        os.rename(DEFAULT_TOKEN_FILE, token_file)
    except OSError:
        pass
# repo layout: <root>/core/commands.json ; HA vendored copy: alongside this file
COMMANDS_FILE = next(
    (p for p in (
        os.path.join(_HERE, "core", "commands.json"),
        os.path.join(_HERE, "commands.json"),
    ) if os.path.exists(p)),
    os.path.join(_HERE, "core", "commands.json"),
)

