class OtpRequired(Exception):
    """The saved token is missing/expired and interactive OTP enrollment is needed."""


class ClientError(Exception):
    """Any other failure worth reporting to the caller verbatim."""


class CommandUnconfirmed(ClientError):
    """A control command's HTTP request timed out (or the car itself never
    answered) -- Kia's own protocol gives no ID-less way to ask afterward
    "did anything get queued for this vehicle?", so whether the command
    actually landed is genuinely unknown, not "failed". A subclass of
    ClientError so existing `except ClientError` callers keep working
    unchanged; callers that care about the distinction can catch this
    specifically to avoid treating a blind retry as safe."""


# ---------------------------------------------------------------------------
# JSON helpers (shared with the bridge's vehicle dump)
# ---------------------------------------------------------------------------
def jsonable(value):
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return value.isoformat()
    if isinstance(value, datetime.timezone):
        return str(value)
    if isinstance(value, (list, tuple)):
        return [jsonable(v) for v in value]
    if isinstance(value, dict):
        return {str(k): jsonable(v) for k, v in value.items()}
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    # hyundai_kia_connect_api sets several Vehicle fields (engine_type, most
    # notably) to a plain `Enum` member, not the `.value` string the field's
    # own type annotation claims -- Python's plain Enum.__str__ renders as
    # "ENGINE_TYPES.EV", not "EV", so falling through to the generic
    # str(value) below would silently serialize engine_type as the literal,
    # useless string "ENGINE_TYPES.EV" instead of "EV". Every consumer
    # matching on this field (e.g. a car-diagram powertrain picker mapping
    # "ICE"/"PHEV"/"HEV"/"EV" to gas/hybrid/ev) would then just never match
    # anything and silently fall back to its default.
    if isinstance(value, enum.Enum):
        return jsonable(value.value)
    return str(value)


def _flatten_scalar_seq(val):
    if isinstance(val, (list, tuple)):
        parts = [str(x) for x in val if x is not None and x != ""]
        return ", ".join(parts) if parts else None
    return val


def dump_vehicle(vehicle):
    """Every readable public attribute + property off the Vehicle object."""
    out = {}
    for attr in dir(vehicle):
        if attr.startswith("_"):
            continue
        try:
            val = getattr(vehicle, attr)
        except Exception:
            continue
        if callable(val):
            continue
        if isinstance(val, (list, tuple)) and all(
            not isinstance(x, (list, tuple, dict)) for x in val
        ):
            val = _flatten_scalar_seq(val)
        try:
            out[attr] = jsonable(val)
        except Exception:
            out[attr] = repr(val)
    try:
        out["data"] = jsonable(getattr(vehicle, "data", {}) or {})
    except Exception:
        pass

    # The library pairs each temperature / distance with the account's local
    # unit (°F + miles for USA & Canada) but stores the raw value — while every
    # downstream formatter (state.js, visuals.js, the HA sensors' device classes)
    # assumes °C / km. Normalise here, the one place both surfaces share.
    _F = ("F", "°F", "FAHRENHEIT")
    _MI = ("MI", "MILES", "MILE")
    for base in ("air_temperature", "outside_temperature"):
        unit = getattr(vehicle, "_" + base + "_unit", None)
        val = out.get(base)
        if isinstance(val, (int, float)) and not isinstance(val, bool) and \
                str(unit).strip().upper() in _F:
            out[base] = round((val - 32) * 5.0 / 9.0, 1)
    for base in (
        "odometer", "ev_driving_range", "total_driving_range",
        "fuel_driving_range", "next_service_distance", "last_service_distance",
    ):
        unit = getattr(vehicle, "_" + base + "_unit", None)
        val = out.get(base)
        if isinstance(val, (int, float)) and not isinstance(val, bool) and \
                str(unit).strip().upper() in _MI:
            out[base] = round(val * 1.609344, 1)
            if base + "_unit" in out:
                out[base + "_unit"] = "km"

    # Domain-range guard: NaN/Infinity/coordinate-range hardening already
    # exists throughout the HA coordinator (_haversine_km, _zone_radius_m,
    # _valid_ll) for GPS specifically -- this is the equivalent for the
    # vehicle's own percentage/range readings, at the one place both MM and
    # HA share (dump_vehicle() is this shared function's whole job). A
    # structurally-valid-looking but semantically impossible reading (Kia's
    # API has been seen, rarely, to report a battery percentage outside
    # 0-100 mid-sync) becomes None ("no data this poll") rather than a fake
    # but plausible-looking number -- clamping to a boundary instead could
    # read as a genuine "fully charged"/"empty" and trigger a false alert,
    # where None just means the next poll's real value is awaited, the same
    # as any other momentarily-missing field.
    for key in ("ev_battery_percentage", "ev_battery_soh_percentage",
                "car_battery_percentage", "fuel_level"):
        val = out.get(key)
        if isinstance(val, (int, float)) and not isinstance(val, bool):
            if not math.isfinite(val) or val < 0 or val > 100:
                out[key] = None
    for key in ("odometer", "ev_driving_range", "total_driving_range",
                "fuel_driving_range"):
        val = out.get(key)
        if isinstance(val, (int, float)) and not isinstance(val, bool):
            if not math.isfinite(val) or val < 0:
                out[key] = None

    return out


def load_commands():
    with open(COMMANDS_FILE, encoding="utf-8") as fh:
        return json.load(fh).get("commands", [])


# ---------------------------------------------------------------------------
# token.json
# ---------------------------------------------------------------------------
def _load_token(token_file, Token, token_dict=None):
    """Prefer an inline token dict (HA config entry); fall back to token.json."""
    raw = None
    if isinstance(token_dict, dict) and token_dict:
        raw = token_dict
    elif token_file and os.path.exists(token_file):
        try:
            with open(token_file, encoding="utf-8") as fh:
                raw = json.load(fh)
        except Exception:
            raw = None
    if not raw:
        return None, None
    try:
        return Token.from_dict(raw), raw.get("enrolled_at")
    except Exception:
        return None, None


def token_dict(vm, enrolled_at=None):
    """Serialise vm.token for storage, keeping the original enrolment time."""
    if vm.token is None:
        return None
    tok = vm.token.to_dict()
    tok["enrolled_at"] = enrolled_at or datetime.datetime.now(
        datetime.timezone.utc
    ).isoformat()
    return tok


def _save_token(token_file, vm, enrolled_at, account_hash=None):
    if vm.token is None:
        return
    # Write-then-rename (same pattern node_helper.js's persist() uses for the
    # vehicle cache): a catastrophic interruption -- power loss, the process
    # killed -- mid-write used to be able to leave token_file itself
    # truncated/corrupt, since the write truncated it in place. Writing to a
    # sibling .tmp file first and only replacing the real file with an
    # atomic os.replace() means the real file is always either the old
    # complete token or the new complete one, never a partial write.
    tmp = token_file + ".tmp"
    try:
        tok = vm.token.to_dict()
        tok["enrolled_at"] = enrolled_at or datetime.datetime.now(
            datetime.timezone.utc
        ).isoformat()
        # Identity tag -- see _migrate_legacy_token()'s comment for why this
        # exists: it's what stops a SECOND account's setup from ever being
        # able to adopt an already-tagged file belonging to a DIFFERENT
        # account during the legacy-token.json migration.
        if account_hash:
            tok["_kiaAccessAccountHash"] = account_hash
        # Create already owner-only rather than open()-then-chmod(): the
        # latter briefly leaves the refresh token world/group-readable
        # (whatever the umask allows) between the write and the chmod call --
        # a real window on every token rotation, not just at enrollment.
        fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            json.dump(tok, fh, indent=2, default=str)
        os.chmod(tmp, stat.S_IRUSR | stat.S_IWUSR)
        os.replace(tmp, token_file)  # atomic on both POSIX and Windows
    except Exception as exc:  # noqa: BLE001
        # non-fatal (the caller already has a good fetch to hand back this
        # cycle) but must NOT be silent -- a failed rotation here means the
        # next run authenticates with a stale token and fails for a reason
        # that's invisible without this line.
        _LOGGER.warning("Kia Access: could not persist rotated token to %s: %s",
                         token_file, exc)
        try:
            os.unlink(tmp)
        except OSError:
            pass


